package com.loopers.application.queue
import com.loopers.infrastructure.queue.RedisAdmissionStore;import org.assertj.core.api.Assertions.assertThat;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.data.redis.connection.lettuce.LettuceConnectionFactory;import org.springframework.data.redis.core.RedisTemplate;import org.springframework.data.redis.serializer.StringRedisSerializer;import java.util.concurrent.*
@SpringBootTest class QueueCapacityTest @Autowired constructor(private val service:AdmissionService,private val store:RedisAdmissionStore){@AfterEach fun clean(){store.clear()};@Test fun capacityDuplicateAndTerminalReleaseAreAtomic(){assertThat(service.admit("w1",3)).isEqualTo(AdmissionService.Result.ACCEPTED);assertThat(service.admit("w1",3)).isEqualTo(AdmissionService.Result.ACCEPTED);assertThat(service.admit("w2",3)).isEqualTo(AdmissionService.Result.ACCEPTED);assertThat(service.admit("w3",3)).isEqualTo(AdmissionService.Result.ACCEPTED);assertThat(service.admit("w4",3)).isEqualTo(AdmissionService.Result.REJECTED);assertThat(store.pending()).isEqualTo(3);service.completed("w2");assertThat(service.admit("w4",3)).isEqualTo(AdmissionService.Result.ACCEPTED);service.failed("w3");assertThat(store.pending()).isEqualTo(2)};@Test fun twoRequestsForLastSlotAcceptExactlyOne(){service.admit("w1",3);service.admit("w2",3);val start=CountDownLatch(1);Executors.newFixedThreadPool(2).use{p->val a=p.submit<AdmissionService.Result>{start.await();service.admit("w3",3)};val b=p.submit<AdmissionService.Result>{start.await();service.admit("w4",3)};start.countDown();assertThat(listOf(a.get(),b.get()).count{it==AdmissionService.Result.ACCEPTED}).isEqualTo(1)}};@Test fun totalRedisOutageFailsClosed(){val f=LettuceConnectionFactory("127.0.0.1",1);f.afterPropertiesSet();val r=RedisTemplate<String,String>();r.connectionFactory=f;r.keySerializer=StringRedisSerializer();r.valueSerializer=StringRedisSerializer();r.hashKeySerializer=StringRedisSerializer();r.hashValueSerializer=StringRedisSerializer();r.afterPropertiesSet();try{assertThat(AdmissionService(RedisAdmissionStore(r)).admit("w1",3)).isEqualTo(AdmissionService.Result.REJECTED)}finally{f.destroy()}}}
